package com.oms.service;
import com.oms.config.Db;import com.oms.dao.*;import com.oms.model.*;import java.math.BigDecimal;import java.sql.*;import java.time.LocalDate;import java.util.*;
public class WarehouseTransferService {
 public record LineInput(long productId,BigDecimal quantity){} public record Saved(long id,String code,String status){}
 private final WarehouseTransferDao dao=new WarehouseTransferDao();private final AuditLogDao audit=new AuditLogDao();
 public WarehouseTransferDao.PageData page()throws SQLException{try(Connection c=Db.getConnection()){return dao.page(c);}}
 public Saved create(LocalDate date,long source,long destination,String note,List<LineInput> lines,boolean send,User actor)throws SQLException{if(date==null)throw new ServiceException("Chọn ngày chuyển.");if(source<=0||destination<=0||source==destination)throw new ServiceException("Kho đi và kho đến phải khác nhau.");if(!inScope(actor,source)&&!inScope(actor,destination))throw new ForbiddenException("Phiếu không thuộc kho bạn phụ trách.");if(lines==null||lines.isEmpty())throw new ServiceException("Phiếu cần ít nhất một mặt hàng.");Set<Long> products=new HashSet<>();for(LineInput l:lines)if(l.productId()<=0||l.quantity()==null||l.quantity().signum()<=0||!products.add(l.productId()))throw new ServiceException("Mặt hàng hoặc số lượng chuyển không hợp lệ.");String clean=note==null?"":note.strip();if(clean.length()>500)throw new ServiceException("Ghi chú tối đa 500 ký tự.");return Db.inTransaction(c->{String code=String.format("CK%06d",dao.next(c));long id=dao.insert(c,code,date,source,destination,clean,actor.getId());for(LineInput l:lines)dao.insertLine(c,id,l.productId(),l.quantity());WarehouseTransferDao.Transfer t=dao.lock(c,id);if(send){if(!inScope(actor,t.sourceId()))throw new ForbiddenException("Bạn không phụ trách kho đi.");dao.send(c,t,actor.getId());}audit.log(c,actor.getId(),send?"WAREHOUSE_TRANSFER_SEND":"WAREHOUSE_TRANSFER_CREATE","WAREHOUSE_TRANSFER",id,code+" · "+lines.size()+" dòng");return new Saved(id,code,send?"IN_TRANSIT":"DRAFT");});}
 public Saved send(long id,User actor)throws SQLException{return Db.inTransaction(c->{var t=dao.lock(c,id);if(t==null||!"DRAFT".equals(t.status()))throw new ServiceException("Phiếu không còn ở trạng thái nháp.");if(!inScope(actor,t.sourceId()))throw new ForbiddenException("Bạn không phụ trách kho đi.");dao.send(c,t,actor.getId());audit.log(c,actor.getId(),"WAREHOUSE_TRANSFER_SEND","WAREHOUSE_TRANSFER",id,t.code());return new Saved(id,t.code(),"IN_TRANSIT");});}
 public Saved receive(long id,List<BigDecimal> quantities,String reason,User actor)throws SQLException{return Db.inTransaction(c->{var t=dao.lock(c,id);if(t==null||!"IN_TRANSIT".equals(t.status()))throw new ServiceException("Phiếu không ở trạng thái đang chuyển.");if(!inScope(actor,t.destinationId()))throw new ForbiddenException("Bạn không phụ trách kho đến.");if(quantities.size()!=t.items().size())throw new ServiceException("Số dòng thực nhận không hợp lệ.");boolean diff=false;for(int i=0;i<quantities.size();i++){BigDecimal q=quantities.get(i);if(q==null||q.signum()<0)throw new ServiceException("Số thực nhận không hợp lệ.");diff|=q.compareTo(t.items().get(i).sent())!=0;}String clean=reason==null?"":reason.strip();if(diff&&clean.isEmpty())throw new ServiceException("Nhập lý do chênh lệch.");dao.receive(c,t,quantities,clean,actor.getId());String status=diff?"DISCREPANCY":"RECEIVED";audit.log(c,actor.getId(),"WAREHOUSE_TRANSFER_RECEIVE","WAREHOUSE_TRANSFER",id,t.code()+" · "+status);return new Saved(id,t.code(),status);});}
 private static boolean inScope(User actor,long warehouse){return actor.isAdmin()||actor.getWarehouses().stream().map(NamedItem::getId).anyMatch(id->id==warehouse);}
}
